records = [r for r in LEGACY_RECORDS if r['source'] == '/Users/cora/Documents/GitHub/lean-llm-opt/Test_Dataset/Large-scale-or/Mixture_testing/Mixture7/15.csv']
header = None
for r in records:
    if r['values'].get('Task Time Required') == 'Worker':
        header = r['values']
        break
if header is None:
    raise ValueError('Header row not found in LEGACY_RECORDS.')
tasks = [k for k in header.keys() if k != 'Task Time Required' and k.strip() != '']
workers = []
cost = {}
for r in records:
    row = r['values']
    worker = row['Task Time Required']
    if worker == 'Worker':
        continue
    workers.append(worker)
    cost[worker] = {}
    for t in tasks:
        v = row[t]
        if v.strip() == '':
            raise ValueError(f'Missing cost for worker {worker}, task {t}')
        cost[worker][t] = int(v)
if len(workers) != 12 or len(tasks) != 10:
    raise ValueError('Unexpected number of workers or tasks.')
m = gp.Model('work_assignment')
x_vars = m.addVars(workers, tasks, vtype=GRB.BINARY, name='')
y_vars = m.addVars(workers, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((cost[i][j] * x_vars[i, j] for i in workers for j in tasks)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[i, j] for i in workers)) == 1 for j in tasks), name='')
m.addConstrs((gp.quicksum((x_vars[i, j] for j in tasks)) == y_vars[i] for i in workers), name='')
m.addConstr(gp.quicksum((y_vars[i] for i in workers)) == 10, name='select_10')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')